CREATE PROCEDURE [purchase].[Purchase_Post] @SupplierId UNIQUEIDENTIFIER,@SupplierInvoiceNo NVARCHAR(100)=NULL,@InvoiceDate DATETIMEOFFSET,@DueDate DATETIMEOFFSET=NULL,@WarehouseId UNIQUEIDENTIFIER,@ItemsJson NVARCHAR(MAX),@ExpensesJson NVARCHAR(MAX)=NULL,@PaymentsJson NVARCHAR(MAX)=NULL,@BillDiscount DECIMAL(18,2)=0,@RoundOff DECIMAL(18,2)=0,@Remarks NVARCHAR(1000)=NULL,@Status NVARCHAR(20)='POSTED',@CreatedBy NVARCHAR(256)=NULL AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF @Status NOT IN('DRAFT','POSTED')THROW 51200,'Invalid purchase status.',1;IF NOT EXISTS(SELECT 1 FROM purchase.Suppliers WHERE SupplierId=@SupplierId AND IsActive=1 AND IsDeleted=0)THROW 51200,'Active supplier is required.',1;IF NOT EXISTS(SELECT 1 FROM inventory.Warehouses WHERE WarehouseId=@WarehouseId AND IsActive=1 AND IsDeleted=0)THROW 51200,'Active warehouse is required.',1;IF ISJSON(@ItemsJson)<>1 OR NOT EXISTS(SELECT 1 FROM OPENJSON(@ItemsJson))THROW 51200,'Purchase requires items.',1;
DECLARE @Id UNIQUEIDENTIFIER=NEWID(),@SeriesId UNIQUEIDENTIFIER,@Prefix NVARCHAR(20),@Next BIGINT,@Len INT,@No NVARCHAR(50),@Subtotal DECIMAL(18,2),@ItemDiscount DECIMAL(18,2),@Tax DECIMAL(18,2),@Expenses DECIMAL(18,2)=0,@Grand DECIMAL(18,2),@Paid DECIMAL(18,2)=0,@Tx UNIQUEIDENTIFIER=NEWID();SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;
SELECT TOP(1)@SeriesId=PurchaseSeriesId,@Prefix=Prefix,@Next=NextNumber,@Len=NumberLength FROM purchase.PurchaseSeries WITH(UPDLOCK,HOLDLOCK)WHERE IsDefault=1 AND IsActive=1;IF @SeriesId IS NULL BEGIN ROLLBACK;THROW 51200,'Purchase series is not configured.',1;END;SET @No=CONCAT(@Prefix,'-',RIGHT(REPLICATE('0',@Len)+CONVERT(NVARCHAR(20),@Next),@Len));UPDATE purchase.PurchaseSeries SET NextNumber=NextNumber+1 WHERE PurchaseSeriesId=@SeriesId;
SELECT @Subtotal=SUM(Quantity*PurchasePrice),@ItemDiscount=SUM(CASE WHEN DiscountAmount>0 THEN DiscountAmount ELSE Quantity*PurchasePrice*DiscountPercentage/100 END),@Tax=SUM((Quantity*PurchasePrice-CASE WHEN DiscountAmount>0 THEN DiscountAmount ELSE Quantity*PurchasePrice*DiscountPercentage/100 END)*GSTPercentage/100)FROM OPENJSON(@ItemsJson)WITH(Quantity DECIMAL(18,4),PurchasePrice DECIMAL(18,4),DiscountPercentage DECIMAL(5,2),DiscountAmount DECIMAL(18,2),GSTPercentage DECIMAL(5,2));IF ISJSON(@ExpensesJson)=1 SELECT @Expenses=ISNULL(SUM(Amount),0)FROM OPENJSON(@ExpensesJson)WITH(Amount DECIMAL(18,2));SET @Grand=ROUND(@Subtotal-@ItemDiscount-@BillDiscount+@Tax+@Expenses+@RoundOff,2);IF ISJSON(@PaymentsJson)=1 SELECT @Paid=ISNULL(SUM(Amount),0)FROM OPENJSON(@PaymentsJson)WITH(Amount DECIMAL(18,2));IF @Paid>@Grand BEGIN ROLLBACK;THROW 51200,'Payment exceeds purchase total.',1;END;
INSERT purchase.PurchaseInvoices(PurchaseInvoiceId,InvoiceNumber,SupplierId,SupplierInvoiceNo,InvoiceDate,DueDate,WarehouseId,Subtotal,DiscountAmount,TaxAmount,ExpenseAmount,RoundOff,GrandTotal,PaidAmount,Status,Remarks,CreatedBy)VALUES(@Id,@No,@SupplierId,@SupplierInvoiceNo,@InvoiceDate,@DueDate,@WarehouseId,@Subtotal,@ItemDiscount+@BillDiscount,@Tax,@Expenses,@RoundOff,@Grand,@Paid,@Status,@Remarks,@CreatedBy);IF @Status='POSTED'INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionDate,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@Tx,@No+'-STK',@InvoiceDate,'PURCHASE','PURCHASE_INVOICE',@Id,@WarehouseId,@Remarks,@CreatedBy);
DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT ProductId,Barcode,BatchNo,ExpiryDate,Quantity,FreeQuantity,PurchasePrice,MRP,SellingPrice,DiscountPercentage,DiscountAmount,GSTPercentage FROM OPENJSON(@ItemsJson)WITH(ProductId UNIQUEIDENTIFIER,Barcode NVARCHAR(100),BatchNo NVARCHAR(100),ExpiryDate DATE,Quantity DECIMAL(18,4),FreeQuantity DECIMAL(18,4),PurchasePrice DECIMAL(18,4),MRP DECIMAL(18,4),SellingPrice DECIMAL(18,4),DiscountPercentage DECIMAL(5,2),DiscountAmount DECIMAL(18,2),GSTPercentage DECIMAL(5,2));DECLARE @Product UNIQUEIDENTIFIER,@Barcode NVARCHAR(100),@Batch NVARCHAR(100),@Expiry DATE,@Qty DECIMAL(18,4),@Free DECIMAL(18,4),@Price DECIMAL(18,4),@MRP DECIMAL(18,4),@Sell DECIMAL(18,4),@DPct DECIMAL(5,2),@Disc DECIMAL(18,2),@GSTPct DECIMAL(5,2),@GST DECIMAL(18,2),@Line DECIMAL(18,2),@Allocated DECIMAL(18,2),@Balance UNIQUEIDENTIFIER,@OldQty DECIMAL(18,4),@OldCost DECIMAL(18,4),@StockQty DECIMAL(18,4),@NewCost DECIMAL(18,4);OPEN c;FETCH NEXT FROM c INTO @Product,@Barcode,@Batch,@Expiry,@Qty,@Free,@Price,@MRP,@Sell,@DPct,@Disc,@GSTPct;WHILE @@FETCH_STATUS=0 BEGIN IF @Qty<=0 OR @Price<0 OR @MRP<@Sell OR NOT EXISTS(SELECT 1 FROM master.Products WHERE ProductId=@Product AND IsActive=1 AND IsDeleted=0)BEGIN CLOSE c;DEALLOCATE c;ROLLBACK;THROW 51200,'Invalid purchase item.',1;END;SET @Disc=CASE WHEN ISNULL(@Disc,0)>0 THEN @Disc ELSE @Qty*@Price*ISNULL(@DPct,0)/100 END;SET @GST=(@Qty*@Price-@Disc)*ISNULL(@GSTPct,0)/100;SET @Line=ROUND(@Qty*@Price-@Disc+@GST,2);SET @Allocated=CASE WHEN @Subtotal>0 THEN @Expenses*(@Qty*@Price)/@Subtotal ELSE 0 END;INSERT purchase.PurchaseInvoiceItems(PurchaseInvoiceId,ProductId,Barcode,BatchNo,ExpiryDate,Quantity,FreeQuantity,PurchasePrice,MRP,SellingPrice,DiscountPercentage,DiscountAmount,GSTPercentage,GSTAmount,AllocatedExpense,LineTotal)VALUES(@Id,@Product,@Barcode,NULLIF(@Batch,''),@Expiry,@Qty,ISNULL(@Free,0),@Price,@MRP,@Sell,ISNULL(@DPct,0),@Disc,ISNULL(@GSTPct,0),@GST,@Allocated,@Line);
IF @Status='POSTED'BEGIN SET @Balance=NULL;SET @OldQty=0;SET @OldCost=0;SET @StockQty=@Qty+ISNULL(@Free,0);SELECT @Balance=InventoryBalanceId,@OldQty=QuantityOnHand,@OldCost=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK)WHERE ProductId=@Product AND WarehouseId=@WarehouseId AND ZoneId IS NULL AND BinId IS NULL AND ISNULL(BatchNo,'')=ISNULL(@Batch,'') AND SerialNo IS NULL;IF @Balance IS NULL BEGIN SET @Balance=NEWID();SET @OldQty=0;SET @OldCost=0;INSERT inventory.InventoryBalances(InventoryBalanceId,ProductId,WarehouseId,BatchNo,QuantityOnHand,AverageCost,LastPurchaseCost,CreatedBy)VALUES(@Balance,@Product,@WarehouseId,NULLIF(@Batch,''),0,0,@Price,@CreatedBy);END;SET @NewCost=CASE WHEN @OldQty+@StockQty=0 THEN @Price ELSE ((@OldQty*@OldCost)+(@Qty*@Price-@Disc+@Allocated))/(@OldQty+@StockQty) END;UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand+@StockQty,AverageCost=@NewCost,LastPurchaseCost=@Price,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@Balance;INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,BatchNo,Quantity,UnitCost)VALUES(@Tx,@Product,NULLIF(@Batch,''),@StockQty,@NewCost);INSERT inventory.InventoryValuation(ProductId,WarehouseId,ValuationMethod,Quantity,UnitCost,ValuationDate)VALUES(@Product,@WarehouseId,'AVERAGE',@OldQty+@StockQty,@NewCost,@InvoiceDate);UPDATE master.Products SET PurchasePrice=@Price,MRP=@MRP,SellingPrice=@Sell,ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE ProductId=@Product;END;FETCH NEXT FROM c INTO @Product,@Barcode,@Batch,@Expiry,@Qty,@Free,@Price,@MRP,@Sell,@DPct,@Disc,@GSTPct;END;CLOSE c;DEALLOCATE c;
IF ISJSON(@ExpensesJson)=1 INSERT purchase.PurchaseExpenses(PurchaseInvoiceId,ExpenseType,Description,Amount,IsTaxable)SELECT @Id,ExpenseType,Description,Amount,IsTaxable FROM OPENJSON(@ExpensesJson)WITH(ExpenseType NVARCHAR(50),Description NVARCHAR(250),Amount DECIMAL(18,2),IsTaxable BIT);IF ISJSON(@PaymentsJson)=1 INSERT purchase.PurchasePayments(PurchaseInvoiceId,PaymentMethodId,Amount,ReferenceNumber,CreatedBy)SELECT @Id,m.PaymentMethodId,j.Amount,j.ReferenceNumber,@CreatedBy FROM OPENJSON(@PaymentsJson)WITH(MethodCode NVARCHAR(30),Amount DECIMAL(18,2),ReferenceNumber NVARCHAR(100))j JOIN sales.PaymentMethods m ON m.MethodCode=j.MethodCode AND m.IsActive=1;COMMIT;SELECT @Id PurchaseInvoiceId,@No InvoiceNumber,@Grand GrandTotal,@Paid PaidAmount,@Grand-@Paid BalanceAmount,@Status Status;END;
